//! Bit-packed tile masks in the SDK's linear layout, plus the static terrain.
//!
//! `Bitboard::export_linear_buffer` returns `ceil(w*h/8)` bytes, row-major with
//! index `y*width + x`, least-significant bit first (verified with the fuel
//! benchmark bot). Exporting costs ~1.7k fuel per mask on a 100×100 map, so the
//! bot does it once at start-up and reads bits in guest memory afterwards.

use crate::bc_core::geom::Pos;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BitGrid {
    width: i32,
    height: i32,
    bits: Vec<u8>,
}

impl BitGrid {
    #[must_use]
    pub fn new(width: i32, height: i32) -> Self {
        let len = (width.max(0) as usize * height.max(0) as usize).div_ceil(8);
        Self { width, height, bits: vec![0; len] }
    }

    /// Wrap an SDK linear export. Returns `None` if the length doesn't match.
    #[must_use]
    pub fn from_linear(width: i32, height: i32, bits: Vec<u8>) -> Option<Self> {
        let expected = (width.max(0) as usize * height.max(0) as usize).div_ceil(8);
        (bits.len() == expected).then_some(Self { width, height, bits })
    }

    #[must_use]
    pub fn width(&self) -> i32 {
        self.width
    }

    #[must_use]
    pub fn height(&self) -> i32 {
        self.height
    }

    #[must_use]
    pub fn in_bounds(&self, p: Pos) -> bool {
        p.x >= 0 && p.y >= 0 && p.x < self.width && p.y < self.height
    }

    #[must_use]
    pub fn get(&self, p: Pos) -> bool {
        if !self.in_bounds(p) {
            return false;
        }
        let i = (p.y * self.width + p.x) as usize;
        self.bits[i >> 3] >> (i & 7) & 1 == 1
    }

    pub fn set(&mut self, p: Pos, value: bool) {
        if !self.in_bounds(p) {
            return;
        }
        let i = (p.y * self.width + p.x) as usize;
        if value {
            self.bits[i >> 3] |= 1 << (i & 7);
        } else {
            self.bits[i >> 3] &= !(1 << (i & 7));
        }
    }

    #[must_use]
    pub fn count_ones(&self) -> u32 {
        self.bits.iter().map(|b| b.count_ones()).sum()
    }

    /// All set positions. Scans every tile in guest code: ~150k fuel on a
    /// 100×100 map. Never call in a bot turn; use the SDK's
    /// `Bitboard::positions()` (~600 fuel) instead. Fine for tests and tools.
    #[must_use]
    pub fn positions(&self) -> Vec<Pos> {
        let mut out = Vec::new();
        for y in 0..self.height {
            for x in 0..self.width {
                let p = Pos::new(x, y);
                if self.get(p) {
                    out.push(p);
                }
            }
        }
        out
    }

    #[must_use]
    pub fn as_bytes(&self) -> &[u8] {
        &self.bits
    }
}

/// Static map layers. Built once from SDK exports.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Terrain {
    pub walls: BitGrid,
    pub holes: BitGrid,
    pub bushes: BitGrid,
    pub altars: BitGrid,
    pub ally_spawn: BitGrid,
    pub enemy_spawn: BitGrid,
    /// Precombined walkability so hot loops do one lookup instead of five.
    walk: BitGrid,
}

impl Terrain {
    #[must_use]
    pub fn new(
        walls: BitGrid,
        holes: BitGrid,
        bushes: BitGrid,
        altars: BitGrid,
        ally_spawn: BitGrid,
        enemy_spawn: BitGrid,
    ) -> Self {
        let (w, h) = (walls.width(), walls.height());
        let mut walk = BitGrid::new(w, h);
        for (i, byte) in walk.bits.iter_mut().enumerate() {
            let blocked = walls.bits[i] | holes.bits[i] | altars.bits[i] | enemy_spawn.bits[i];
            *byte = !blocked;
        }
        // Clear padding bits past the last tile.
        let cells = (w.max(0) * h.max(0)) as usize;
        if !cells.is_multiple_of(8) {
            if let Some(last) = walk.bits.last_mut() {
                *last &= (1u8 << (cells % 8)) - 1;
            }
        }
        Self { walls, holes, bushes, altars, ally_spawn, enemy_spawn, walk }
    }

    #[must_use]
    pub fn width(&self) -> i32 {
        self.walls.width()
    }

    #[must_use]
    pub fn height(&self) -> i32 {
        self.walls.height()
    }

    /// Ordinary walking: no walls, holes, altars or enemy spawn.
    #[must_use]
    pub fn walkable(&self, p: Pos) -> bool {
        self.walk.get(p)
    }

    /// Dashes may cross holes but never walls; they still can't land on holes.
    #[must_use]
    pub fn dash_passable(&self, p: Pos) -> bool {
        self.walls.in_bounds(p) && !self.walls.get(p)
    }

    #[must_use]
    pub fn opaque(&self, p: Pos) -> bool {
        self.walls.get(p) || self.bushes.get(p)
    }

    /// Parse an ASCII fixture for tests. Line `i` is row `y = i`.
    ///
    /// `#` wall, `o` hole, `"` bush, `A` altar, `S` ally spawn, `E` enemy spawn,
    /// anything else is open floor.
    #[must_use]
    pub fn from_ascii(rows: &[&str]) -> Self {
        let height = rows.len() as i32;
        let width = rows.iter().map(|r| r.chars().count()).max().unwrap_or(0) as i32;
        let mut layers: [BitGrid; 6] = core::array::from_fn(|_| BitGrid::new(width, height));
        for (y, row) in rows.iter().enumerate() {
            for (x, c) in row.chars().enumerate() {
                let p = Pos::new(x as i32, y as i32);
                let layer = match c {
                    '#' => 0,
                    'o' => 1,
                    '"' => 2,
                    'A' => 3,
                    'S' => 4,
                    'E' => 5,
                    _ => continue,
                };
                layers[layer].set(p, true);
            }
        }
        let [walls, holes, bushes, altars, ally_spawn, enemy_spawn] = layers;
        Self::new(walls, holes, bushes, altars, ally_spawn, enemy_spawn)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn linear_layout_matches_sdk_probe() {
        // Fuel-bench probe on a 100×100 map: (1,0) set → byte0 = 0b10;
        // (0,1) set → byte 12 = 0b0001_0000.
        let mut g = BitGrid::new(100, 100);
        g.set(Pos::new(1, 0), true);
        g.set(Pos::new(0, 1), true);
        assert_eq!(g.as_bytes()[0], 0b10);
        assert_eq!(g.as_bytes()[12], 0b0001_0000);
        let round_trip = BitGrid::from_linear(100, 100, g.as_bytes().to_vec()).unwrap();
        assert!(round_trip.get(Pos::new(0, 1)) && round_trip.get(Pos::new(1, 0)));
        assert!(!round_trip.get(Pos::new(1, 1)));
    }

    #[test]
    fn from_linear_rejects_wrong_length() {
        assert!(BitGrid::from_linear(10, 10, vec![0; 12]).is_none());
        assert!(BitGrid::from_linear(10, 10, vec![0; 13]).is_some());
    }

    #[test]
    fn out_of_bounds_reads_false_and_writes_are_ignored() {
        let mut g = BitGrid::new(4, 4);
        g.set(Pos::new(-1, 0), true);
        g.set(Pos::new(4, 0), true);
        assert_eq!(g.count_ones(), 0);
        assert!(!g.get(Pos::new(9, 9)));
    }

    #[test]
    fn terrain_walkability() {
        let t = Terrain::from_ascii(&["S.#", "oA.", "\"E."]);
        assert!(t.walkable(Pos::new(0, 0)), "own spawn is walkable");
        assert!(!t.walkable(Pos::new(2, 0)), "wall");
        assert!(!t.walkable(Pos::new(0, 1)), "hole");
        assert!(!t.walkable(Pos::new(1, 1)), "altar");
        assert!(!t.walkable(Pos::new(1, 2)), "enemy spawn");
        assert!(t.walkable(Pos::new(0, 2)), "bush is walkable");
        assert!(t.dash_passable(Pos::new(0, 1)), "dash crosses holes");
        assert!(!t.dash_passable(Pos::new(2, 0)), "dash never crosses walls");
        assert!(t.opaque(Pos::new(0, 2)) && t.opaque(Pos::new(2, 0)));
        assert!(!t.walkable(Pos::new(3, 0)) && !t.walkable(Pos::new(0, -1)), "out of bounds");
    }

    #[test]
    fn combined_walk_grid_ignores_padding_bits() {
        // 3×3 = 9 cells → 2 bytes, 7 padding bits that must stay clear.
        let t = Terrain::from_ascii(&["...", "...", "..."]);
        assert_eq!(t.walk.count_ones(), 9);
    }
}
